<template><main class="library-page"><span class="eyebrow">SUA BIBLIOTECA</span><h1>Minhas playlists</h1><p>Arraste pela alça ⋮⋮ para ordenar ou mover entre listas. No celular, toque e deslize a alça. Os botões também funcionam com teclado.</p><p v-if="!user.user" class="notice">Entre na sua conta para criar playlists.</p><p v-if="library.error || library.pending.length" class="notice">{{ library.error || 'Sincronizando alterações…' }}</p><p v-if="error" role="alert" class="error">{{ error }}</p><form class="library-toolbar" @submit.prevent="create"><input v-model="name" maxlength="80" placeholder="Nome da nova playlist" aria-label="Nome da playlist"/><button class="primary" :disabled="!user.user || creating">{{ creating?'Criando…':'Criar playlist' }}</button></form><div class="playlist-columns"><section v-for="(id,pane) in [selected,target]" :key="pane" class="library-card"><label>{{ pane===0?'Sua playlist':'Mover para outra playlist' }}<select :disabled="creating || dragging" :value="id" :aria-label="pane===0?'Selecionar playlist':'Playlist de destino'" @change="pane===0?selected=$event.target.value:target=$event.target.value"><option value="">{{ pane===0?'Escolha uma playlist':'Escolha o destino' }}</option><option v-for="p in library.playlists.filter(p=>pane===0||p.id!==selected)" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><template v-if="getList(id)"><h2>{{ getList(id).name }}</h2><FolderSummary :tracks="playable(id)"/><div class="library-actions"><button @click="play(id)" :disabled="!playable(id).length">Ouvir playlist</button><button @click="enqueue(id,'offline')">Salvar offline</button><button @click="enqueue(id,'zip')">Baixar ZIP</button><button @click="rename(id)">Renomear</button><button @click="remove(id)">Excluir playlist</button></div><Draggable :model-value="rows(id)" @update:model-value="updateRows(id,$event)" item-key="key" :group="{name:'playlists',pull:true,put:true}" handle=".drag-handle" :animation="150" :force-fallback="true" :fallback-on-body="true" :fallback-tolerance="4" :delay="0" ghost-class="music-drag-placeholder" chosen-class="music-drag-selected" fallback-class="music-drag-preview" @start="beginDrag" :move="canMove" @end="persistOrder" class="playlist-tracks" :aria-label="'Faixas de '+getList(id).name"><template #item="{element,index}"><article class="library-row"><button type="button" class="drag-handle" title="Arrastar para ordenar" :aria-label="'Arrastar '+element.track.title"><i class="mdi mdi-drag"/></button><div class="track-info"><strong>{{ element.track.title }}</strong><small>{{ element.track.cantor || 'Faixa indisponível no catálogo' }}</small></div><div class="library-actions"><button @click="listen(element.track)" :disabled="!element.track.downloadUrl" :aria-label="'Ouvir '+element.track.title"><i class="mdi mdi-play"/></button><button @click="reorder(id,index,-1)" :disabled="index===0" :aria-label="'Subir '+element.track.title">↑</button><button @click="reorder(id,index,1)" :disabled="index===rows(id).length-1" :aria-label="'Descer '+element.track.title">↓</button><button v-if="pane===0 && target" @click="move(element.key)" :aria-label="'Mover '+element.track.title+' para outra playlist'">Mover</button><button @click="erase(id,element.key)" :aria-label="'Remover '+element.track.title+' da playlist'">✕</button></div></article></template></Draggable><p v-if="!rows(id).length">Lista vazia. Adicione músicas pelo catálogo ou salve a fila do player.</p></template><p v-else>{{ pane===0?'Crie ou escolha uma playlist.':'Abra uma segunda lista para arrastar músicas entre elas.' }}</p></section></div></main></template>
<script setup>
import {ref,computed,onMounted,watch,nextTick} from 'vue';import Draggable from 'vuedraggable';import FolderSummary from '@/components/FolderSummary.vue';import {getCatalog} from '@/services/catalog';import {useLibraryStore} from '@/stores/useLibraryStore';import {useUserStore} from '@/stores/userStore';import {usePlayerStore} from '@/stores/usePlayerStore';import {useDownloadStore} from '@/stores/useDownloadStore';import {trackKey} from '@/utils/media';
const library=useLibraryStore(),user=useUserStore(),player=usePlayerStore(),downloads=useDownloadStore(),name=ref(''),selected=ref(''),target=ref(''),error=ref(''),catalog=ref([]),creating=ref(false),dragging=ref(false)
const byKey=computed(()=>new Map(catalog.value.map(t=>[trackKey(t),t]))),getList=id=>library.playlists.find(p=>p.id===id)
const rowsOf=id=>(getList(id)?.trackIds||[]).map(key=>({key,track:byKey.value.get(key)||{title:'Música indisponível',id:key}}))
const selectedRows=computed(()=>rowsOf(selected.value)),targetRows=computed(()=>rowsOf(target.value))
const rows=id=>id===selected.value?selectedRows.value:id===target.value?targetRows.value:rowsOf(id),playable=id=>rows(id).map(r=>r.track).filter(t=>t.downloadUrl)
let dragOwner=''
function beginDrag(){dragOwner=library.owner;dragging.value=true}
async function attempt(fn){error.value='';try{return await fn()}catch(e){error.value=e.message}}
watch(()=>library.playlists.map(p=>p.id),ids=>{if(!ids.includes(selected.value))selected.value=ids[0]||'';if(!ids.includes(target.value)||target.value===selected.value)target.value='';},{immediate:true});watch(selected,()=>{if(target.value===selected.value)target.value=''})
async function create(){if(creating.value)return;creating.value=true;try{const id=await attempt(()=>library.create(name.value));if(id){selected.value=id;name.value=''}}finally{creating.value=false}}
function rename(id){const value=window.prompt('Novo nome da playlist',getList(id).name);if(value!==null)attempt(()=>library.change(id,{name:value}))}
function remove(id){if(window.confirm('Excluir esta playlist? As músicas e os arquivos offline permanecem.'))attempt(()=>library.remove(id))}
function updateRows(id,value){const p=getList(id);if(p)p.trackIds=[...new Set(value.map(r=>r.key))]}
function canMove(e){const related=e.relatedContext.list;return !related||(!related.some(r=>r.key===e.draggedContext.element.key)&&related.length<500)||e.from===e.to}
async function persistOrder(){await nextTick();dragging.value=false;if(dragOwner!==library.owner)return;await attempt(()=>library.saveLists([getList(selected.value),getList(target.value)].filter(Boolean)))}
function reorder(id,index,offset){const p=getList(id),ids=[...p.trackIds];[ids[index],ids[index+offset]]=[ids[index+offset],ids[index]];attempt(()=>library.change(id,{trackIds:ids}))}
function move(key){attempt(()=>library.move(selected.value,target.value,key))}
function erase(id,key){attempt(()=>library.change(id,{trackIds:getList(id).trackIds.filter(k=>k!==key)}))}
function play(id){player.replaceQueue(playable(id));if(player.error)error.value=player.error}
function listen(track){player.addToQueue(track,{playNow:true});if(player.error)error.value=player.error}
function enqueue(id,mode){attempt(()=>downloads.enqueue(playable(id),mode,getList(id).name))}
onMounted(()=>attempt(async()=>{catalog.value=await getCatalog()}))
</script>
<style scoped>.playlist-columns{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.library-card{min-width:0}.library-card label{display:grid;gap:8px}.library-card h2{margin:18px 0 8px}.playlist-tracks{min-height:100px;padding-top:14px}.drag-handle{touch-action:none;cursor:grab;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;min-width:44px;flex-shrink:0}.drag-handle:active{cursor:grabbing}.sortable-ghost{opacity:.35;border:1px dashed #58d994}.track-info strong{font-size:14px}@media(max-width:800px){.playlist-columns{grid-template-columns:1fr}}</style>